// Renders the publication and patent lists from data.js.
// data.js is generated by tools/xlsx2data.py and is already sorted.
(function () {
  'use strict';

  var DATA = window.HCDRC_DATA || {};
  var PUBS = DATA.publications || [];
  var PATENTS = DATA.patents || [];

  var PUB_TYPES = { conference: 'Conference', journal: 'Journal' };

  function esc(value) {
    return String(value == null ? '' : value).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }

  // Titles written in Korean or Japanese get a lang attribute so the whole title is drawn in one
  // CJK font (see :lang(ko) / :lang(ja) in main.css) instead of mixing it with Roboto.
  function langAttr(text) {
    if (/[\u3040-\u30ff]/.test(text)) return ' lang="ja"';
    if (/[\uac00-\ud7a3]/.test(text)) return ' lang="ko"';
    return '';
  }

  function emptyState(text) {
    return '<p class="empty-state">' + esc(text) + '</p>';
  }

  /* ---------------------------------------------------------- Publications */

  function publicationItem(p) {
    var title = p.url
      ? '<a class="title"' + langAttr(p.title) + ' href="' + esc(p.url) + '" target="_blank" rel="noopener noreferrer">' + esc(p.title) + '</a>'
      : '<span class="title"' + langAttr(p.title) + '>' + esc(p.title) + '</span>';
    return '<li>' +
      '<span class="tag">' + esc(PUB_TYPES[p.type] || p.type) + '</span>' + title +
      '<div class="periodical">' + esc(p.venue) + (p.year ? ' ' + esc(p.year) : '') + '</div>' +
      '</li>';
  }

  function renderPublications(el) {
    if (!PUBS.length) {
      el.innerHTML = emptyState('No publications yet.');
      return;
    }
    // Publications arrive newest first; start a new group whenever the year changes.
    var html = '';
    var current;
    PUBS.forEach(function (p, i) {
      var y = p.year || 'Unknown';
      if (i === 0 || y !== current) {
        if (i > 0) html += '</ol>';
        html += '<h2 class="year-heading" id="y' + esc(y) + '">' + esc(y) + '</h2><ol class="bibliography">';
        current = y;
      }
      html += publicationItem(p);
    });
    el.innerHTML = html + '</ol>';
  }

  /* --------------------------------------------------------------- Patents */

  function patentItem(p) {
    return '<li>' +
      '<span class="tag">' + esc(p.country) + '</span>' +
      '<span class="title"' + langAttr(p.title) + '>' + esc(p.title) + '</span>' +
      '</li>';
  }

  function patentSection(id, heading, items) {
    if (!items.length) return '';
    return '<h2 class="year-heading" id="' + id + '">' + esc(heading) + '</h2>' +
      '<ol class="bibliography">' + items.map(patentItem).join('') + '</ol>';
  }

  function renderPatents(el) {
    if (!PATENTS.length) {
      el.innerHTML = emptyState('No patents yet.');
      return;
    }
    el.innerHTML =
      patentSection('registered', 'International Patents (Registered)',
        PATENTS.filter(function (p) { return p.status === 'registered'; })) +
      patentSection('applications', 'International Patents (Filed)',
        PATENTS.filter(function (p) { return p.status !== 'registered'; }));
  }

  /* ------------------------------------------------------------------ Init */

  var targets = {
    'publication-list': renderPublications,
    'patent-list': renderPatents
  };

  Object.keys(targets).forEach(function (id) {
    var el = document.getElementById(id);
    if (el) targets[id](el);
  });

  // Re-apply the URL hash after rendering so in-page links land on the right heading.
  if (window.location.hash) {
    var target = document.getElementById(window.location.hash.slice(1));
    if (target) target.scrollIntoView();
  }
})();
